def skill():
    P = {1: Rational(1, 2), 2: Rational(1, 4), 4: Rational(1, 4)}
    m = sum(p*x for x, p in P.items())
    s2 = sum(p*x**2 for x, p in P.items()) - m**2
    v = s2/6 + m**2
    return v.p + v.q

def standard():
    from itertools import product
    vals = [1, 1, 2, 4]
    tot = Fraction(0)
    for t in product(vals, repeat=6):
        tot += Fraction(sum(t), 6)**2
    v = tot / 4**6
    return v.numerator + v.denominator

def unique():
    return [standard()]
